import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class CustomerRecordMapperTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String describe(Customer c) {
        return c == null ? "no customer" : c.toString();
    }

    public static void main(String[] args) {
        try {
            Customer full = CustomerRecordMapper.toCustomer(
                    DbRow.of("id", 7, "name", "  Ada ", "email", "ADA@X.COM", "active", true));
            check("a complete row maps cleanly",
                    "Customer[id=7, name=Ada, email=ada@x.com, active=true]", describe(full));

            Customer sparse = CustomerRecordMapper.toCustomer(DbRow.of("id", null));
            check("missing columns fall back to defaults",
                    "Customer[id=0, name=(unknown), email=, active=false]", describe(sparse));

            Customer blankName = CustomerRecordMapper.toCustomer(
                    DbRow.of("id", 3, "name", "   ", "email", null, "active", false));
            check("a blank name becomes (unknown)", "(unknown)",
                    blankName == null ? "no customer" : blankName.name());
            check("a null email becomes the empty string", "",
                    blankName == null ? "no customer" : blankName.email());

            Customer falsy = CustomerRecordMapper.toCustomer(
                    DbRow.of("id", 11, "name", "Bob", "email", " Bob@Example.COM ", "active", null));
            check("email is trimmed and lowercased", "bob@example.com",
                    falsy == null ? "no customer" : falsy.email());
            check("a null Boolean becomes false", Boolean.FALSE,
                    falsy == null ? "no customer" : Boolean.valueOf(falsy.active()));

            List<DbRow> rows = Arrays.asList(
                    DbRow.of("id", 2, "name", "Two", "email", "t@x", "active", true),
                    DbRow.of("id", 1, "name", "One", "email", "o@x", "active", false));
            List<Customer> mapped = CustomerRecordMapper.toCustomers(rows);
            check("two rows map to two customers", 2, mapped == null ? -1 : mapped.size());
            check("row order is preserved", 2,
                    mapped == null || mapped.isEmpty() ? -1 : mapped.get(0).id());
            check("an empty list maps to an empty list", 0,
                    CustomerRecordMapper.toCustomers(new ArrayList<DbRow>()).size());
            check("a null list maps to an empty list", 0,
                    CustomerRecordMapper.toCustomers(null).size());
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

