import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Provided -- do not edit. The domain object a row is mapped into. */
record Customer(int id, String name, String email, boolean active) {
}

/**
 * Provided -- do not edit. One row of a result set: column names to raw values,
 * exactly as a JDBC driver would hand them over (any type, possibly null).
 */
class DbRow {
    private final Map<String, Object> cells = new LinkedHashMap<>();

    static DbRow of(Object... columnsThenValues) {
        DbRow row = new DbRow();
        for (int i = 0; i + 1 < columnsThenValues.length; i += 2) {
            row.cells.put(String.valueOf(columnsThenValues[i]), columnsThenValues[i + 1]);
        }
        return row;
    }

    Object get(String column) {
        return cells.get(column);
    }
}

/**
 * TASK: Write the row mapper that turns raw database rows into Customer records.
 *
 * toCustomer(row) reads four columns and defends against missing data:
 *   "id"     an Integer  -- null or missing becomes 0
 *   "name"   a String    -- trimmed; null, missing or blank becomes "(unknown)"
 *   "email"  a String    -- lowercased and trimmed; null or missing becomes ""
 *   "active" a Boolean   -- null or missing becomes false
 *
 * toCustomers(rows) maps a whole list, keeping the order. A null list maps to
 * an empty list.
 *
 * Example: DbRow.of("id", 7, "name", "  Ada ", "email", "ADA@X.COM", "active", true)
 *          -> Customer[id=7, name=Ada, email=ada@x.com, active=true]
 *          DbRow.of("id", null) -> Customer[id=0, name=(unknown), email=, active=false]
 *
 * The raw values arrive as Object, so you have to cast them -- for example
 * (Integer) row.get("id") -- after checking for null.
 */
public class CustomerRecordMapper {

    public static Customer toCustomer(DbRow row) {
        Object rawId = row.get("id");
        int id = (rawId == null) ? 0 : ((Integer) rawId).intValue();

        Object rawName = row.get("name");
        String name = (rawName == null) ? "" : ((String) rawName).trim();
        if (name.isEmpty()) {
            name = "(unknown)";
        }

        Object rawEmail = row.get("email");
        String email = (rawEmail == null)
                ? ""
                : ((String) rawEmail).trim().toLowerCase(java.util.Locale.ROOT);

        Object rawActive = row.get("active");
        boolean active = (rawActive != null) && ((Boolean) rawActive).booleanValue();

        return new Customer(id, name, email, active);
    }

    public static List<Customer> toCustomers(List<DbRow> rows) {
        List<Customer> result = new ArrayList<>();
        if (rows == null) {
            return result;
        }
        for (DbRow row : rows) {
            result.add(toCustomer(row));
        }
        return result;
    }
}
